import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, ListGroup, Modal, Form, Badge } from 'react-bootstrap';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';
import Confetti from 'react-confetti';
import 'bootstrap/dist/css/bootstrap.min.css';
import '../App.css';

// Register all necessary Chart.js components
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const workoutPlan = {
  "workout_plan": {
    "goal": "Reduce weight and achieve a proper body figure similar to an actress within 4 months",
    "target_audience": { "age": 24, "weight_kg": 62, "height_ft": 5.3, "experience": "Beginner", "focus_areas": ["body fat", "belly fat"] },
    "schedule": { "days_per_week": 5, "time": "6:00 AM - 7:00 AM", "duration_minutes": 60 },
    "days": [
      {
        "day": 1, "name": "Full Body Beginner Workout", "objective": "Get the body moving, burn calories, and activate muscles",
        "exercises": [
          {"name": "Warm-Up (Dynamic Stretching)", "reps": "-", "sets": "-", "rest": "-"},
          {"name": "Step-Ups", "reps": "30 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Bodyweight Squats", "reps": "12-15", "sets": 3, "rest": "30 sec"},
          {"name": "Glute Bridges", "reps": "12-15", "sets": 3, "rest": "30 sec"},
          {"name": "Standing Leg Raises (each leg)", "reps": 12, "sets": 3, "rest": "20 sec"},
          {"name": "Seated Knee Lifts (Core)", "reps": 12, "sets": 3, "rest": "30 sec"},
          {"name": "Plank (Knee Plank)", "reps": "20 sec", "sets": 3, "rest": "30 sec"},
          {"name": "Cool Down & Stretching", "reps": "-", "sets": "-", "rest": "-"}
        ],
        "benefits": "Activates all major muscle groups and boosts metabolism"
      },
      {
        "day": 2, "name": "Lower Body Focus", "objective": "Strengthen legs and glutes, burn lower body fat",
        "exercises": [
          {"name": "Warm-Up (Dynamic Stretching)", "reps": "-", "sets": "-", "rest": "-"},
          {"name": "Step-Ups", "reps": "30 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Wall Sit", "reps": "20-30 sec", "sets": 3, "rest": "30 sec"},
          {"name": "Donkey Kicks (each leg)", "reps": 12, "sets": 3, "rest": "20 sec"},
          {"name": "Side Leg Raises (each leg)", "reps": 12, "sets": 3, "rest": "20 sec"},
          {"name": "Glute Bridges", "reps": "12-15", "sets": 3, "rest": "30 sec"},
          {"name": "Cool Down & Stretching", "reps": "-", "sets": "-", "rest": "-"}
        ],
        "benefits": "Targets thighs, glutes, and calves for toning and fat loss"
      },
      {
        "day": 3, "name": "Core and Cardio", "objective": "Burn belly fat and strengthen core muscles",
        "exercises": [
          {"name": "Warm-Up (Dynamic Stretching)", "reps": "-", "sets": "-", "rest": "-"},
          {"name": "Step-Ups", "reps": "30 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Mountain Climbers (Knee-Friendly)", "reps": "20 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Seated Knee Lifts (Core)", "reps": 12, "sets": 3, "rest": "30 sec"},
          {"name": "Bicycle Crunches", "reps": 10, "sets": 3, "rest": "30 sec"},
          {"name": "Plank (Knee Plank)", "reps": "20 sec", "sets": 3, "rest": "30 sec"},
          {"name": "Cool Down & Stretching", "reps": "-", "sets": "-", "rest": "-"}
        ],
        "benefits": "Enhances core stability and increases heart rate for fat burning"
      },
      {
        "day": 4, "name": "Upper Body and Mobility", "objective": "Tone arms and improve flexibility",
        "exercises": [
          {"name": "Warm-Up (Dynamic Stretching)", "reps": "-", "sets": "-", "rest": "-"},
          {"name": "Arm Circles (forward & backward)", "reps": "20 sec each", "sets": 3, "rest": "20 sec"},
          {"name": "Wall Push-Ups", "reps": "10-12", "sets": 3, "rest": "30 sec"},
          {"name": "Standing Shoulder Shrugs", "reps": 15, "sets": 3, "rest": "20 sec"},
          {"name": "Seated Twist (each side)", "reps": 10, "sets": 3, "rest": "20 sec"},
          {"name": "Step-Ups", "reps": "30 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Cool Down & Stretching", "reps": "-", "sets": "-", "rest": "-"}
        ],
        "benefits": "Improves upper body strength and mobility"
      },
      {
        "day": 5, "name": "Full Body Fat Burn", "objective": "Maximize calorie burn and overall toning",
        "exercises": [
          {"name": "Warm-Up (Dynamic Stretching)", "reps": "-", "sets": "-", "rest": "-"},
          {"name": "Step-Ups", "reps": "30 sec", "sets": 3, "rest": "20 sec"},
          {"name": "Bodyweight Squats", "reps": "12-15", "sets": 3, "rest": "30 sec"},
          {"name": "Glute Bridges", "reps": "12-15", "sets": 3, "rest": "30 sec"},
          {"name": "Seated Knee Lifts (Core)", "reps": 12, "sets": 3, "rest": "30 sec"},
          {"name": "Wall Push-Ups", "reps": "10-12", "sets": 3, "rest": "30 sec"},
          {"name": "Cool Down & Stretching", "reps": "-", "sets": "-", "rest": "-"}
        ],
        "benefits": "Combines strength and cardio for full-body fat loss"
      }
    ]
  }
};

const startQuotes = ["Begin with elegance, end with strength!", "Your journey to luxury starts now!", "Step into greatness today!"];
const endQuotes = ["A masterpiece completed!", "You’re a star—shine on!", "Luxury is your reward!"];

const WorkoutPlanner = () => {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [displayedWorkout, setDisplayedWorkout] = useState(null);
  const [workoutData] = useState(workoutPlan.workout_plan);
  const [completedExercises, setCompletedExercises] = useState({});
  const [progress, setProgress] = useState({});
  const [savedWorkouts, setSavedWorkouts] = useState({});
  const [startTime, setStartTime] = useState(null);
  const [exerciseTrackers, setExerciseTrackers] = useState({});
  const [showStartModal, setShowStartModal] = useState(false);
  const [showEndModal, setShowEndModal] = useState(false);
  const [selfie, setSelfie] = useState(null);
  const [currentQuote] = useState(startQuotes[Math.floor(Math.random() * startQuotes.length)]);
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    const savedProgress = JSON.parse(localStorage.getItem('workoutProgress')) || {};
    const savedWorkouts = JSON.parse(localStorage.getItem('savedWorkouts')) || {};
    setProgress(savedProgress);
    setSavedWorkouts(savedWorkouts);
    setDisplayedWorkout(getWorkoutForDate(selectedDate));
  }, [selectedDate]);

  useEffect(() => {
    localStorage.setItem('workoutProgress', JSON.stringify(progress));
    localStorage.setItem('savedWorkouts', JSON.stringify(savedWorkouts));
  }, [progress, savedWorkouts]);

  const getWorkoutForDate = (date) => {
    const dayOfWeek = date.getDay();
    return (dayOfWeek >= 1 && dayOfWeek <= 5) ? workoutData.days[dayOfWeek - 1] : null;
  };

  const handleTileClick = (date) => {
    const workout = getWorkoutForDate(date);
    setDisplayedWorkout(workout);
  };

  const startWorkout = () => {
    setStartTime(new Date());
    setShowStartModal(true);
  };

  const finishWorkout = () => {
    setShowEndModal(true);
    setShowConfetti(true);
    setTimeout(() => setShowConfetti(false), 7000);
  };

  const toggleExerciseCompletion = (day, exerciseIndex) => {
    const dateKey = selectedDate.toDateString();
    const newCompleted = { ...completedExercises };
    if (!newCompleted[dateKey]) newCompleted[dateKey] = {};
    newCompleted[dateKey][exerciseIndex] = !newCompleted[dateKey][exerciseIndex];
    setCompletedExercises(newCompleted);

    const totalExercises = displayedWorkout?.exercises.length || 0;
    const completedCount = Object.values(newCompleted[dateKey] || {}).filter(Boolean).length;
    setProgress((prev) => ({
      ...prev,
      [dateKey]: { completed: completedCount, total: totalExercises },
    }));

    if (completedCount === totalExercises) finishWorkout();
  };

  const saveWorkout = () => {
    const dateKey = selectedDate.toDateString();
    const endTime = new Date();
    const duration = startTime ? Math.round((endTime - startTime) / 60000) : 0;
    setSavedWorkouts((prev) => ({
      ...prev,
      [dateKey]: {
        startTime: startTime?.toISOString(),
        endTime: endTime.toISOString(),
        duration,
        exercises: exerciseTrackers[dateKey] || {},
        selfie,
      },
    }));
    setShowEndModal(false);
    setStartTime(null);
    setExerciseTrackers((prev) => ({ ...prev, [dateKey]: {} }));
    setSelfie(null);
  };

  const handleSelfieUpload = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => setSelfie(reader.result);
    if (file) reader.readAsDataURL(file);
  };

  const getExerciseDetails = (exerciseName) => {
    const instructions = {
      "Warm-Up (Dynamic Stretching)": "Perform 5 minutes of arm circles, neck rolls, and side bends.",
      "Step-Ups": "Step onto a low platform or stair with one foot, then the other, and step down. Repeat.",
      "Bodyweight Squats": "Stand with feet shoulder-width apart, squat down, then return to standing.",
      "Glute Bridges": "Lie on your back, knees bent, lift hips toward the ceiling, then lower.",
      "Standing Leg Raises (each leg)": "Stand straight, lift one leg forward, hold briefly, then switch.",
      "Seated Knee Lifts (Core)": "Sit on a chair, lift knees toward chest, then lower.",
      "Plank (Knee Plank)": "Rest on knees and elbows, hold body straight for the duration.",
      "Cool Down & Stretching": "Perform 5 minutes of gentle stretches for all major muscle groups.",
      "Wall Sit": "Lean against a wall, slide down to a seated position, hold.",
      "Donkey Kicks (each leg)": "On all fours, kick one leg back and up, then switch.",
      "Side Leg Raises (each leg)": "Lie on your side, lift top leg up, then lower.",
      "Mountain Climbers (Knee-Friendly)": "In a plank position on knees, bring one knee to chest, then switch.",
      "Bicycle Crunches": "Lie on back, alternate touching elbow to opposite knee.",
      "Arm Circles (forward & backward)": "Extend arms, make small circles forward, then backward.",
      "Wall Push-Ups": "Face a wall, place hands on it, bend elbows to lower chest, then push back.",
      "Standing Shoulder Shrugs": "Lift shoulders toward ears, hold, then release.",
      "Seated Twist (each side)": "Sit, twist torso to one side, hold, then switch."
    };
    const referenceLinks = {
      "Warm-Up (Dynamic Stretching)": "https://www.youtube.com/watch?v=MkYdJZlfgCo",
      "Step-Ups": "https://www.youtube.com/watch?v=zvZHgUyz6VI",
      "Bodyweight Squats": "https://www.youtube.com/watch?v=aclHkVaku9U",
      "Glute Bridges": "https://www.youtube.com/watch?v=OUsk4wAzaRI",
      "Standing Leg Raises (each leg)": "https://www.youtube.com/watch?v=4J5HpxH79HU",
      "Seated Knee Lifts (Core)": "https://www.youtube.com/watch?v=hrL2N8Y7W8c",
      "Plank (Knee Plank)": "https://www.youtube.com/watch?v=1AtMXPKuRIg",
      "Cool Down & Stretching": "https://www.youtube.com/watch?v=7Z9l5miUhxQ",
      "Wall Sit": "https://www.youtube.com/watch?v=y-wV4Venusw",
      "Donkey Kicks (each leg)": "https://www.youtube.com/watch?v=Sj7ZfO7lYno",
      "Side Leg Raises (each leg)": "https://www.youtube.com/watch?v=6Q0F0wv2_hU",
      "Mountain Climbers (Knee-Friendly)": "https://www.youtube.com/watch?v=nmwgirgXLYM",
      "Bicycle Crunches": "https://www.youtube.com/watch?v=9FGilxCbdz8",
      "Arm Circles (forward & backward)": "https://www.youtube.com/watch?v=WnL7mYdRQBw",
      "Wall Push-Ups": "https://www.youtube.com/watch?v=5N_1qTcUR3Q",
      "Standing Shoulder Shrugs": "https://www.youtube.com/watch?v=NhNq8rVntNA",
      "Seated Twist (each side)": "https://www.youtube.com/watch?v=8XbO1TAvZYI"
    };
    return {
      instructions: instructions[exerciseName] || "Follow the video/image.",
      reference: referenceLinks[exerciseName] || "https://www.youtube.com/watch?v=dQw4w9WgXcQ",
    };
  };

  const chartData = {
    labels: Object.keys(progress).slice(-7).map(date => new Date(date).toLocaleDateString('en-US', { weekday: 'short' })),
    datasets: [
      {
        label: 'Exercises Completed',
        data: Object.values(progress).slice(-7).map(p => p.completed),
        backgroundColor: '#d4af37',
        borderColor: '#ff69b4',
        borderWidth: 2,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          font: {
            size: 16, // Increased font size for clarity
            family: "'Montserrat', sans-serif",
          },
          color: '#d4af37',
        },
      },
      title: {
        display: true,
        text: 'Your Weekly Triumphs',
        font: {
          size: 20,
          family: "'Playfair Display', serif",
        },
        color: '#d4af37',
      },
      tooltip: {
        backgroundColor: '#ff69b4',
        titleFont: { size: 14 },
        bodyFont: { size: 12 },
      },
    },
    scales: {
      x: {
        ticks: {
          font: {
            size: 14,
            family: "'Montserrat', sans-serif",
          },
          color: '#ff69b4',
        },
      },
      y: {
        beginAtZero: true,
        ticks: {
          font: {
            size: 14,
            family: "'Montserrat', sans-serif",
          },
          color: '#ff69b4',
        },
      },
    },
  };

  const isToday = (date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="planner-container">
      <Container fluid className="py-5">
        <h1 className="text-center mb-5"><i className="fas fa-dumbbell me-2"></i>Workout Planner</h1>
        <p className="text-center text-muted mb-5 fs-5"><i className="fas fa-bullseye me-2"></i><strong>Goal:</strong> {workoutData.goal}</p>
        <Row className="justify-content-center">
          <Col xs={12} md={4} lg={3} className="mb-4">
            <Card>
              <Card.Header className="bg-gradient-primary text-white text-center py-3 fs-4"><i className="fas fa-calendar-alt me-2"></i>Workout Calendar</Card.Header>
              <Card.Body className="p-4">
                <Calendar
                  onChange={setSelectedDate}
                  value={selectedDate}
                  className="custom-calendar w-100"
                  tileClassName={({ date }) => {
                    const workout = getWorkoutForDate(date);
                    return workout ? `workout-day day-${workout.day}` : 'rest-day';
                  }}
                  tileContent={({ date }) => (
                    <div className="tile-content" onClick={() => handleTileClick(date)}>
                      {isToday(date) && <span className="today-label">Today</span>}
                      {getWorkoutForDate(date) ? (
                        <span className="workout-label"><i className="fas fa-running me-1"></i>Day {getWorkoutForDate(date).day}</span>
                      ) : (
                        <span className="rest-label"><i className="fas fa-bed me-1"></i>Rest</span>
                      )}
                    </div>
                  )}
                  onClickDay={(value, event) => event.preventDefault()}
                />
              </Card.Body>
            </Card>
          </Col>
          <Col xs={12} md={4} lg={5} className="mb-4">
            <Card>
              <Card.Header className="bg-gradient-success text-white text-center py-3 fs-4">
                <i className="fas fa-dumbbell me-2"></i>{displayedWorkout ? displayedWorkout.name : "Rest Day"} - {selectedDate.toDateString()}
              </Card.Header>
              <Card.Body className="p-4">
                {displayedWorkout ? (
                  <>
                    <div className="d-flex justify-content-center mb-4">
                      <Button variant="primary" onClick={startWorkout} disabled={startTime}>
                        <i className="fas fa-play me-2"></i>Start Workout
                      </Button>
                      {startTime && (
                        <Button variant="warning" className="ms-3" onClick={finishWorkout}>
                          <i className="fas fa-stop me-2"></i>Finish Workout
                        </Button>
                      )}
                    </div>
                    <ListGroup variant="flush">
                      {displayedWorkout.exercises.map((exercise, index) => {
                        const details = getExerciseDetails(exercise.name);
                        const isCompleted = completedExercises[selectedDate.toDateString()]?.[index];
                        return (
                          <ListGroup.Item key={index} className={isCompleted ? 'completed' : ''}>
                            <h5 className="fs-4"><i className="fas fa-running me-2"></i>{exercise.name}</h5>
                            <p className="fs-5"><i className="fas fa-redo me-2"></i><strong>Reps:</strong> {exercise.reps} | <strong>Sets:</strong> {exercise.sets} | <strong>Rest:</strong> {exercise.rest}</p>
                            <p className="text-muted">{details.instructions}</p>
                            <Button
                              variant={isCompleted ? 'outline-danger' : 'success'}
                              onClick={() => toggleExerciseCompletion(displayedWorkout.day, index)}
                              disabled={!startTime}
                            >
                              {isCompleted ? <><i className="fas fa-undo me-2"></i>Undo</> : <><i className="fas fa-check me-2"></i>Done</>}
                            </Button>
                          </ListGroup.Item>
                        );
                      })}
                    </ListGroup>
                  </>
                ) : (
                  <p className="text-center fs-4"><i className="fas fa-bed me-2"></i>Enjoy your rest day in style!</p>
                )}
              </Card.Body>
            </Card>
          </Col>
          <Col xs={12} md={4} lg={4} className="mb-4">
            <Card>
              <Card.Header className="bg-gradient-info text-white text-center py-3 fs-4"><i className="fas fa-chart-bar me-2"></i>Weekly Progress</Card.Header>
              <Card.Body className="p-4" style={{ height: '300px' }}>
                <Bar data={chartData} options={chartOptions} />
              </Card.Body>
            </Card>
          </Col>
        </Row>
        <Modal show={showStartModal} onHide={() => setShowStartModal(false)} centered>
          <Modal.Header closeButton className="bg-gradient-primary text-white">
            <Modal.Title className="fs-3"><i className="fas fa-play me-2"></i>Start Your Luxurious Workout!</Modal.Title>
          </Modal.Header>
          <Modal.Body className="text-center">
            <p className="fs-4">{currentQuote}</p>
          </Modal.Body>
          <Modal.Footer className="justify-content-center">
            <Button variant="primary" onClick={() => setShowStartModal(false)}>
              <i className="fas fa-arrow-right me-2"></i>Let’s Begin!
            </Button>
          </Modal.Footer>
        </Modal>
        <Modal show={showEndModal} onHide={() => setShowEndModal(false)} centered>
          <Modal.Header closeButton className="bg-gradient-success text-white">
            <Modal.Title className="fs-3"><i className="fas fa-trophy me-2"></i>Workout Masterpiece Completed!</Modal.Title>
          </Modal.Header>
          <Modal.Body className="text-center">
            {showConfetti && <Confetti numberOfPieces={300} recycle={false} colors={['#d4af37', '#ff69b4', '#ffffff']} />}
            <Badge bg="warning" text="dark" className="mb-3 fs-5">Achievement Unlocked: Fitness Royalty</Badge>
            <p className="fs-4">{endQuotes[Math.floor(Math.random() * endQuotes.length)]}</p>
            <Form.Group>
              <Form.Label className="fs-5"><i className="fas fa-camera me-2"></i>Capture Your Triumph!</Form.Label>
              <Form.Control type="file" accept="image/*" onChange={handleSelfieUpload} />
              {selfie && <img src={selfie} alt="Workout Selfie" className="mt-3 rounded" style={{ maxWidth: '100%', border: '3px solid #d4af37' }} />}
            </Form.Group>
          </Modal.Body>
          <Modal.Footer className="justify-content-center">
            <Button variant="success" onClick={saveWorkout}>
              <i className="fas fa-save me-2"></i>Save Your Victory
            </Button>
          </Modal.Footer>
        </Modal>
      </Container>
    </div>
  );
};

export default WorkoutPlanner;